from pathlib import Path
p=Path('tmp/pdfs')
removed=0
for pattern in ['page-*.txt','manuscript.txt','render-*.png','main-*.png','theory-*.png']:
    for f in p.glob(pattern):
        if f.is_file():
            f.unlink()
            removed += 1
p.rmdir()
try:
    p.parent.rmdir()
except OSError:
    pass
print('Removed', removed, 'temporary extraction and rendering files; manuscript unchanged.')
